struct Point { int x, y; };

struct Rect {
    struct Point tl, br;
    const char *name;
};

// Designated Initializers (C99+)
struct Rect window = {
    .name = "Main",
    .tl.x = 0,
    .br.y = 100
};

// Designated Initializers for Arrays
int primes[] = { [2]=5, [0]=2, [1]=3 };
// primes is { 2, 3, 5 }

// Compound Literal for struct (C99+)
struct Point center = (struct Point){ .x = 50, .y = 50 };

// Compound Literal for Array
int *arr_ptr = (int[]){ 10, 20, 30 };
// arr_ptr has automatic storage duration

// Initializing Nested Structure via Compound Literal
struct Rect complex_rect = {
    .tl = (struct Point){ 10, 10 },
    .br = (struct Point){ 50, 50 }
};
